
-- Batch 8: Ivory Coast, Japan, Kenya, Korea, Lebanon, remaining African, others
UPDATE recipes SET continent = 'Africa', history = 'Attiéké with Grilled Chicken is Ivory Coast''s beloved street food pairing. Attiéké is a fermented cassava couscous unique to Ivorian cuisine, created by the Ébrié people of southern Ivory Coast. This light, fluffy side dish paired with grilled chicken represents the innovative food traditions of Côte d''Ivoire.' WHERE slug = 'attieke-grilled-chicken';

UPDATE recipes SET continent = 'Asia', history = 'Sushi originated as a preservation method in Southeast Asia, arriving in Japan around the 8th century. Modern nigiri sushi was created by Hanaya Yohei in Edo (Tokyo) in the 1820s as fast food for busy merchants. Today, sushi is Japan''s most famous culinary export and a UNESCO-recognized cultural practice.' WHERE slug = 'sushi-japanese';

UPDATE recipes SET continent = 'Global', history = 'Ramen Carbonara is a fusion dish blending Japanese ramen with Italian carbonara, representing the creative cross-pollination of two of the world''s most beloved pasta/noodle traditions. This innovative combination emerged from the global food fusion movement of the 2010s.' WHERE slug = 'ramen-carbonara';

UPDATE recipes SET continent = 'Asia', history = 'Matcha Cheesecake combines the American-style cheesecake with Japanese matcha green tea. Matcha has been central to Japanese tea ceremony (chado) since the 12th century, when Buddhist monks brought powdered tea from China. This fusion dessert represents Japan''s creative adaptation of Western desserts.' WHERE slug = 'matcha-cheesecake-jp';

UPDATE recipes SET continent = 'Asia', history = 'Pork Gyoza with Dipping Sauce are Japanese pan-fried dumplings that arrived from China after WWII. The Japanese perfected the crispy-bottom technique (yaki-gyoza) and developed a signature dipping sauce of soy, rice vinegar, and chili oil. They became one of Japan''s most popular izakaya and home-cooking dishes.' WHERE slug = 'pork-gyoza-jp';

UPDATE recipes SET continent = 'Asia', history = 'Sushi Rolls (Maki) represent the evolution of traditional sushi into a more accessible format. Maki-zushi, wrapping rice and fillings in nori seaweed, became popular in Japan in the 18th century. The California Roll, invented in the 1960s in North America, further revolutionized sushi for Western palates.' WHERE slug = 'sushi-rolls-jp';

UPDATE recipes SET continent = 'Asia', history = 'Tempura was introduced to Japan by Portuguese missionaries in the 16th century. The word comes from the Latin "tempora" referring to Ember Days when Catholics abstained from meat and ate fried vegetables instead. Japanese chefs perfected the light, crispy batter that makes tempura uniquely Japanese.' WHERE slug = 'tempura-jp';

UPDATE recipes SET continent = 'Africa', history = 'Kachumbari is an East African fresh salad of tomatoes, onions, and chili peppers found across Kenya and Tanzania. This vibrant condiment accompanies grilled meats and starchy staples, providing a refreshing counterpoint. Its simplicity masks its essential role in balancing East African meals.' WHERE slug = 'kachumbari-ke';

UPDATE recipes SET continent = 'Africa', history = 'Sukuma Wiki with Ugali is Kenya''s most consumed daily meal. "Sukuma wiki" means "stretch the week" in Swahili, reflecting its role as an affordable, nutritious staple. The collard greens paired with maize porridge form the backbone of Kenyan home cooking across all economic levels.' WHERE slug = 'sukuma-wiki-ke';

UPDATE recipes SET continent = 'Africa', history = 'Ugali is the staple food of East Africa, a firm cornmeal porridge made from maize flour and water. Since maize arrived from the Americas in the 16th century, ugali has become the daily bread of millions across Kenya, Tanzania, and Uganda, eaten with virtually every meal.' WHERE slug = 'ugali-ke';

UPDATE recipes SET continent = 'Africa', history = 'Githeri is a traditional Kikuyu dish of boiled maize and beans, one of Kenya''s most ancient foods. This nutritious combination has sustained highland communities for centuries, providing complete protein from the complementary amino acids in corn and legumes. It''s the original Kenyan comfort food.' WHERE slug = 'githeri-kenya';

UPDATE recipes SET continent = 'Africa', history = 'Kachumbari is the fresh tomato and onion salad that accompanies virtually every Kenyan meal. This bright, acidic condiment cuts through rich meats and starchy ugali, providing essential vitamins. Its ubiquity across East Africa reflects the importance of fresh vegetables in balanced traditional diets.' WHERE slug = 'kachumbari';

UPDATE recipes SET continent = 'Africa', history = 'Ugali with Sukuma Wiki is the quintessential Kenyan everyday meal. This pairing of firm cornmeal porridge with sautéed collard greens represents the nutritional wisdom of traditional East African diets, combining carbohydrates with iron-rich greens in an affordable, satisfying combination.' WHERE slug = 'ugali-with-sukuma-wiki';

UPDATE recipes SET continent = 'Africa', history = 'Mukimo is a traditional Kikuyu dish from Kenya''s central highlands, a green mash of potatoes, corn, peas, and pumpkin leaves. This colorful dish is central to Kikuyu celebrations and represents the agricultural abundance of the fertile highland region where the Kikuyu have farmed for centuries.' WHERE slug = 'mukimo-kenya-kikuyu';

UPDATE recipes SET continent = 'Africa', history = 'Ingoho is a traditional Luhya chicken preparation from western Kenya. The Luhya people are renowned for their love of chicken, and ingoho is the centerpiece of celebrations and welcome feasts. The dish represents the proud culinary traditions of Kenya''s second-largest ethnic group.' WHERE slug = 'ingoho-luhya-chicken-kenya';

UPDATE recipes SET continent = 'Africa', history = 'Omena Fry features silver cyprinid fish from Lake Victoria, a staple protein source for Luo communities in western Kenya. These tiny dried fish, rich in calcium and omega-3, are fried with onions and tomatoes. Omena represents the lake-based food traditions that have sustained lakeside communities for generations.' WHERE slug = 'omena-fry-silver-cyprinid-kenya-luo';

UPDATE recipes SET continent = 'Africa', history = 'Biriyani ya Pwani (Coastal Biryani) is the Swahili Coast adaptation of the Indian/Persian biryani, brought by Arab and Indian traders to Mombasa and Lamu centuries ago. Kenyan coastal biryani features local spices, coconut milk, and techniques that make it distinctively East African.' WHERE slug = 'biriyani-ya-pwani-kenya-coast';

UPDATE recipes SET continent = 'Africa', history = 'Kaimati/Mahamri are sweet, cardamom-spiced doughnuts from the Swahili Coast of Kenya and Tanzania. These golden treats, often enjoyed with chai, reflect the Indian Ocean spice trade that brought cardamom and other aromatics to East Africa. They''re a beloved breakfast and tea-time snack along the coast.' WHERE slug = 'kaimati-mahamri-breakfast-kenya-tanzania';

UPDATE recipes SET continent = 'Africa', history = 'Mchuzi wa Samaki is a coastal Swahili fish in coconut curry, reflecting centuries of maritime trade that brought coconut palms, spices, and cooking techniques from India and Southeast Asia to East Africa. This aromatic dish is a Mombasa and Zanzibar specialty served at celebrations.' WHERE slug = 'mchuzi-wa-samaki-fish-kenya-tanzania';

UPDATE recipes SET continent = 'Asia', history = 'Crispy Korean Gochujang Wings showcase Korea''s beloved gochujang (fermented chili paste), which has been produced for over 500 years. The combination of crispy fried wings with sweet-spicy gochujang glaze represents the Korean tradition of bold, fermented flavors in modern street food form.' WHERE slug = 'korean-gochujang-wings-kr';

UPDATE recipes SET continent = 'Asia', history = 'Dalgona Coffee went viral during the 2020 COVID-19 lockdowns, originating from South Korea. Named after a Korean honeycomb toffee candy, this whipped coffee drink became one of the most shared recipes in social media history. It represents Korea''s outsized cultural influence in the digital age.' WHERE slug = 'dalgona-coffee-kr';

UPDATE recipes SET continent = 'Asia', history = 'Kimchi Pancakes (Kimchijeon) are a beloved Korean comfort food that transforms fermented kimchi into crispy, savory pancakes. This dish embodies the Korean zero-waste philosophy, using aged kimchi that becomes more sour and flavorful with time. It''s a rainy day tradition in Korea, paired with makgeolli rice wine.' WHERE slug = 'kimchi-pancakes-kr';

UPDATE recipes SET continent = 'Asia', history = 'Hummus with Veggie Sticks represents the modern healthy adaptation of one of the world''s oldest prepared foods. Lebanese hummus, with its roots dating back thousands of years, has become a global health food. This preparation makes the ancient dip accessible as a nutritious snack.' WHERE slug = 'hummus-veggie-lb';

UPDATE recipes SET continent = 'Africa', history = 'Motoho is a traditional Sotho fermented sorghum porridge from Lesotho. This probiotic-rich drink/porridge has sustained mountain communities in the kingdom for centuries. Sorghum, one of Africa''s oldest grains, was domesticated over 5,000 years ago and remains central to Lesotho''s food culture.' WHERE slug = 'motoho-lesotho';

UPDATE recipes SET continent = 'Africa', history = 'Palava Sauce is a Liberian-Ghanaian spinach and palm oil stew that represents the shared culinary heritage of the Upper Guinea Coast. This nutritious dish combines indigenous leafy greens with palm oil and fish, showcasing the West African tradition of one-pot cooking that maximizes both flavor and nutrition.' WHERE slug = 'palava-sauce-liberia-ghana';
